function protectedIp(ip) {
  if (!/^\d+\.\d+\.\d+\.\d+$/.test(ip)) return 'bad_ip';
  if (ip.startsWith('10.250.0.')) return 'team_vpn';
  if (ip === '203.0.113.10') return 'kali_host';
  if (ip === '203.0.113.12') return 'normal_control';   // B 요청(10/26): 정상 대조용 출발지
  const m = ip.match(/^203\.0\.113\.(\d+)$/);
  if (m && +m[1] >= 100 && +m[1] <= 109) return 'normal_source';
  return null;
}
const CFG = { dry_run: true, store_real: false };   // 기본은 관찰 모드. 실제 티켓 기록은 케이스별로 본문 store_real:true일 때만(11/03 D), 실제 조치는 dry_run:false + 별도 승인
// H2 로그인 반복 실패(무차별 대입): count()>8 · 30분 · username + src_ip (A, 임계는 기획서 값, 측정 전)
const t = { ...($input.first().json.body || {}) };
const iso = (v) => (typeof v === 'string' && /T.*(Z|[+-]\d\d:?\d\d)$/.test(v)) && Number.isFinite(Date.parse(v)) ? v : null;
const T = { first_attack_at: iso(t.first_attack_at), condition_met_at: iso(t.condition_met_at), detected_at: iso(t.detected_at), received_at: new Date().toISOString() };
const missing = ['event_id', 'asset_id', 'src_ip', 'username'].filter(k => !t[k]);
if (missing.length) return [{ json: { ok: false, verdict: 'invalid_input', missing } }];
const p = protectedIp(t.src_ip);
if (p) return [{ json: { ok: true, verdict: 'protected_source', reason: p, case_id: 'H2', event_id: t.event_id, src_ip: t.src_ip } }];
if (t.dry_run === false) CFG.dry_run = false;   // 실제 포털 차단은 Graylog 알림 본문의 dry_run:false로만 켠다(기본 true). 켜기 전 D 명시 승인(10/28)
if (t.store_real === true) CFG.store_real = true;   // 실제 티켓 기록(C 저장소)은 본문의 store_real:true(불리언)로만 켠다(기본 false). 케이스별 회차에서만 사용
const X = { seat: 'A', case_id: 'H2', title: 'H2 로그인 반복 실패(무차별 대입)', event_id: t.event_id, asset_id: t.asset_id, src_ip: t.src_ip, username: t.username,
  count: t.count ?? null, group_key: t.username, cfg: CFG, times: T, expected: [{ bot: '112', via: 'portal', action: 'block', target: t.src_ip }] };
return [{ json: { proceed: true, mode: 'check', seat: 'A', group_key: t.username, ctx: X } }];

const validText = v => typeof v === 'string' && v.length > 0 && v.length <= 300 && !/[\x00-\x1f\x7f]/.test(v);
const ticketId = v => typeof v === 'string' && /^T-\d{8}-\d{4}$/.test(v);
const states = ['open','responding','verified','restored','closed'];
const canon = a => a.via === 'pfsense' && a.action === 'fw_block' ? 'block' : a.action;
const same = (a,b) => a.bot === b.bot && a.via === b.via && canon(a) === canon(b) && a.target === b.target;
const refOK = (a, dry=false) => a && typeof a.bot === 'string' && /^(\d{3}|manual)$/.test(a.bot) && ['portal','pfsense','wazuh-ar','manual'].includes(a.via) && typeof a.action === 'string' && /^[a-z][a-z_]{1,31}$/.test(a.action) && validText(a.target) && (a.result === undefined || ['applied','already_applied'].includes(a.result) || (dry && a.result === 'dry_run'));
const held = (ctx,code) => [{json:{ok:false,no_action:true,verdict:code,ctx}}];
const snapshotOK = j => j.ok === true && typeof j.exists === 'boolean' && Array.isArray(j.actions) && j.actions.every(a=>refOK(a,!!j.ctx?.cfg?.dry_run) && (['applied','already_applied'].includes(a.result) || (j.ctx?.cfg?.dry_run && a.result==='dry_run'))) && (j.exists ? ticketId(j.ticket_id) && states.includes(j.status) : j.ticket_id === null && j.status === null && j.actions.length === 0);

const j = $input.first().json, x = j.ctx;
if (!snapshotOK(j)) return held(x,'held_ticket_check');
if (j.exists && (j.status==='closed' || j.status==='restored' && j.actions.length)) return held(x,'held_ticket_cycle');
const expected = x.expected || [{bot:'112',via:'portal',action:'block',target:x.src_ip}];
// dry_run 기록은 30분 안의 것만 처리됨으로 센다(시각이 없거나 오래된 시험 기록이 그 출발지를 영구히 막지 않게).
const DRY_DEDUP_MS = 30 * 60 * 1000;
const fresh = a => { const t = Date.parse(a.finished_at || a.requested_at || ''); const age = Date.now() - t; return Number.isFinite(t) && age >= 0 && age < DRY_DEDUP_MS; };
const done = s => j.actions.some(a => same(a,s) && (['applied','already_applied'].includes(a.result) || (x.cfg.dry_run && a.result === 'dry_run' && fresh(a))));
if (j.exists && expected.length && expected.every(done)) return [{json:{ok:true,no_action:true,verdict:'duplicate_no_action',ticket_id:j.ticket_id,event_id:x.event_id,case_id:x.case_id}}];
return [{json:{ok:true,proceed:true,ctx:{...x,existing_ticket:j.ticket_id,new_round_required:j.exists && j.status==='restored'}}}];

// 조치 전에 티켓을 먼저 만든다(stage detected). 이미 열린 티켓이 있으면 그 티켓을 쓴다.
const x = $input.first().json.ctx;
return [{ json: { ctx: x, mode: 'record', stage: 'detected', seat: x.seat, case_id: x.case_id, group_key: x.group_key, title: x.title,
  asset_id: x.asset_id, src_ip: x.src_ip || null, username: x.username || null, event_ids: [x.event_id],
  first_attack_at: x.times ? x.times.first_attack_at : null, condition_met_at: x.times ? x.times.condition_met_at : null, detected_at: x.times ? x.times.detected_at : null, received_at: x.times ? x.times.received_at : null,
  idempotency_key: `${$execution.id}-detected` } }];

// 티켓 저장(detected)이 실패하면 조치를 하지 않는다. 기록 없는 차단을 막기 위해 조치 노드 앞에서 중단한다.
const r = $input.first().json;
const x = r.ctx || {};
return [{ json: { ok: false, verdict: 'ticket_store_failed_no_action', case_id: x.case_id, event_id: x.event_id, src_ip: x.src_ip || null, username: x.username || null,
  error: { code: (r.error && r.error.code) || 'STORE_FAILED' }, no_action: true, n8n_execution_id: $execution.id } }];

if (($input.first().json.ctx?.results || []).some(s=>['failed','rejected'].includes(s.result))) throw new Error('PREVIOUS_ACTION_FAILED');
const record=$input.first().json;
if (record.ok !== true || !record.ticket_id || !['open','responding','verified'].includes(record.status) || record.ctx?.new_round_required && record.ticket_id===record.ctx.existing_ticket) throw new Error('TICKET_RECORD_REQUIRED');
if (record.ticket_current !== true) throw new Error('TICKET_CURRENT_REQUIRED');
const r = $input.first().json;
const x = r.ctx;
const ticket_id = r.ticket_id || x.ticket_id;
return [{ json: { ctx: { ...x, ticket_id }, ticket_id, dry_run: x.cfg.dry_run, action: 'block', ip: x.src_ip } }];

// 조치 결과를 티켓에 기록(stage applied). 중복 방지 키: {실행 ID}-applied-1
const r = $input.first().json;
const x = r.ctx;
if (r.result === 'skipped') return [{ json: { ctx: x, mode: 'record', stage: 'detected', seat: x.seat, case_id: x.case_id, group_key: x.group_key,
  asset_id: x.asset_id, src_ip: x.src_ip || null, username: x.username || null, event_ids: [x.event_id], idempotency_key: `${$execution.id}-skip-1` } }];
const res = { step: 1, result: r.result, detail: r.detail };
return [{ json: { ctx: { ...x, results: [...(x.results || []), res] }, mode: 'record', stage: 'applied', seat: x.seat, case_id: x.case_id, group_key: x.group_key, title: x.title,
  asset_id: x.asset_id, src_ip: x.src_ip || null, username: x.username || null, event_ids: [x.event_id], idempotency_key: `${$execution.id}-applied-1`,
  action: { bot: '112', target: x.src_ip, via: 'portal', action: 'block', result: r.result,
    applied_verified: r.result === 'dry_run' ? null : (r.applied_verified ?? null), effect_verified: null, effect_verified_at: null,
    requested_at: r.requested_at, finished_at: r.finished_at, n8n_execution_id: String($execution.id), detail: r.detail } } }];

const record=$input.first().json;
if (record.ok !== true || !record.ticket_id || !['open','responding','verified'].includes(record.status) || record.ctx?.new_round_required && record.ticket_id===record.ctx.existing_ticket) throw new Error('TICKET_RECORD_REQUIRED');
const r = $input.first().json;
const x = r.ctx;
const bad = (x.results || []).some(s => ['failed', 'rejected'].includes(s.result));
return [{ json: { ctx: { ...x, ticket: { ok: r.ok, ticket_id: r.ticket_id, status: r.status } }, level: bad ? 'error' : 'warn', case_id: x.case_id, title: x.title,
  src_ip: x.src_ip || undefined, ticket_id: r.ticket_id, result: (x.results || []).map(s => s.result).join(', '),
  detail: (x.username ? `계정 ${x.username} ` : '') + (x.file_key ? `파일 ${x.file_key} ` : '') + (x.results || []).map(s => s.detail).join(' / ') } }];

const r = $input.first().json;
const x = r.ctx;
return [{ json: { ok: !(x.results || [x.block]).filter(Boolean).some(s=>['failed','rejected'].includes(s.result)) && (x.ticket || x.record)?.ok === true, verdict: x.cfg.dry_run ? 'dry_run' : 'responded', case_id: x.case_id, event_id: x.event_id, asset_id: x.asset_id, src_ip: x.src_ip || null, username: x.username || null,
  steps: x.results, ticket: x.ticket, discord_sent: r.sent, discord_error: r.error, n8n_execution_id: $execution.id } }];

